 final int BG=Color.rgb(9,17,30), CARD=Color.rgb(21,31,48), PURPLE=Color.rgb(255,137,43), PINK=Color.rgb(255,175,83), WHITE=Color.WHITE, MUTED=Color.rgb(172,174,197);
 LinearLayout page,list; TextView phase,name,clock,roundLabel,nextLabel,progressLabel,playButton; Ring ring;
 ArrayList<Exercise> exercises=new ArrayList<>(); ArrayList<Step> steps=new ArrayList<>();
 int rounds=3,index=0,remaining=30,stepDuration=30; boolean running=false,done=false; long deadline=0; Handler handler=new Handler(Looper.getMainLooper()); String soundMode="음성 + 알림음";
 final BroadcastReceiver stateReceiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent intent){
 if(!intent.getBooleanExtra("hasPlan",true)){if(!running&&!done)sendPlan();return;}index=intent.getIntExtra("index",index);remaining=intent.getIntExtra("remaining",remaining);running=intent.getBooleanExtra("running",false);done=intent.getBooleanExtra("completed",false);
 if(index<steps.size())stepDuration=steps.get(index).seconds;update();}};
