 void command(String action){Intent i=new Intent(this,WorkoutService.class);i.putExtra("command",action);if("query".equals(action))startService(i);else startForegroundService(i);}
 void sendPlan(){try{JSONArray arr=new JSONArray();for(Step s:steps){JSONObject j=new JSONObject();j.put("name",s.name);j.put("seconds",s.seconds);j.put("round",s.round);j.put("exercise",s.exercise);j.put("set",s.set);j.put("sets",s.sets);j.put("rest",s.rest);arr.put(j);}Intent i=new Intent(this,WorkoutService.class);i.putExtra("command","init");i.putExtra("plan",arr.toString());i.putExtra("mode",soundMode);startForegroundService(i);}catch(Exception ignored){}}
  static class Exercise {String name;int duration,rest,sets;Exercise(String n,int d,int r,int s){name=n;duration=d;rest=r;sets=s;}}
 static class Step {String name;int seconds,round,exercise,set,sets;boolean rest;Step(String n,int sec,int r,int e,int s,int max,boolean b){name=n;seconds=sec;round=r;exercise=e;set=s;sets=max;rest=b;}}
 int dp(float x){return (int)(getResources().getDisplayMetrics().density*x+.5f);} 
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(0);load();if(exercises.isEmpty()){exercises.add(new Exercise("플랭크",30,15,1));exercises.add(new Exercise("스쿼트",45,20,1));exercises.add(new Exercise("팔굽혀펴기",30,30,1));}build();render();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},11);}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);if(bold)t.setTypeface(null,1);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
